{
  "root": "main_stack",
  "state": {
    "itineraryDaysTableData": [
      {
        "id": "day1",
        "day": "Day 1: Shinjuku & Shibuya",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Shinjuku_Gyoen_National_Garden_-_01.jpg/1200px-Shinjuku_Gyoen_National_Garden_-_01.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/geo-alt.svg",
        "activities": "Morning: Shinjuku Gyoen National Garden (¥500).\nAfternoon: Shibuya Crossing and the Hachiko Statue (Free).\nEvening: Metropolitan Government Building for night views (Free).",
        "dining": "Dining: Budget Ramen at Ichiran Shinjuku (¥1,500).",
        "actionLabel": "Shinjuku Guide",
        "actionUrl": "https://www.japan-guide.com/e/e3011.html"
      },
      {
        "id": "day2",
        "day": "Day 2: Akihabara Electric Town",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Akihabara_Electric_Town_2014.jpg/1200px-Akihabara_Electric_Town_2014.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/laptop.svg",
        "activities": "Morning: Browse multi-story electronics stores like Yodobashi Camera (Free).\nAfternoon: Anime and manga shopping at Mandarake and Animate (Free/Variable).\nEvening: Arcade gaming at Taito Station (¥2,000).",
        "dining": "Dining: Casual Curry at Go! Go! Curry (¥1,000).",
        "actionLabel": "Akihabara Map",
        "actionUrl": "https://www.akiba.or.jp/en/"
      }
    ],
    "budgetData": [
      { "Category": "Accommodation", "Day 1": "¥13,500", "Day 2": "¥13,500", "Day 3": "¥13,500", "Day 4": "¥13,500", "Day 5": "¥13,500" },
      { "Category": "Food", "Day 1": "¥4,500", "Day 2": "¥4,000", "Day 3": "¥5,000", "Day 4": "¥4,500", "Day 5": "¥4,000" },
      { "Category": "Transport", "Day 1": "¥1,000", "Day 2": "¥1,200", "Day 3": "¥800", "Day 4": "¥1,500", "Day 5": "¥1,000" },
      { "Category": "Activities", "Day 1": "¥500", "Day 2": "¥2,000", "Day 3": "¥3,000", "Day 4": "¥2,500", "Day 5": "¥1,000" },
      { "Category": "Total", "Day 1": "¥19,500", "Day 2": "¥20,700", "Day 3": "¥22,300", "Day 4": "¥22,000", "Day 5": "¥19,500" }
    ],
    "quickActions": [
      { "label": "Tokyo Metro Map", "url": "https://www.tokyometro.jp/en/subwaymap/" },
      { "label": "Shinjuku Dining", "url": "https://www.timeout.com/tokyo/restaurants/best-restaurants-in-shinjuku" }
    ],
    "sources": [
      { "label": "Go Tokyo", "url": "https://www.gotokyo.org/en/" },
      { "label": "Japan Guide", "url": "https://www.japan-guide.com/" }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": "16"
      },
      "children": [
        "title_shinjuku",
        "subtitle_itinerary",
        "itinerary_table",
        "budget_title",
        "budget_table",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "title_shinjuku": {
      "type": "Text",
      "props": {
        "text": "Shinjuku Solo Exploration",
        "variant": "h1"
      },
      "children": []
    },
    "subtitle_itinerary": {
      "type": "Text",
      "props": {
        "text": "5-Day Technology & Heritage Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itineraryDaysTableData",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "columns": [
          { "key": "day", "label": "Day" },
          { "key": "image", "label": "Image" },
          { "key": "icon", "label": "Icon" },
          { "key": "activities", "label": "Activities" },
          { "key": "dining", "label": "Dining" },
          { "key": "actionLabel", "label": "Action" },
          { "key": "actionUrl", "label": "URL" }
        ]
      },
      "children": []
    },
    "budget_title": {
      "type": "Text",
      "props": {
        "text": "Budget Breakdown (per day)",
        "variant": "h3"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "statePath": "/budgetData",
        "domain": "formula",
        "preferredPresentation": "table",
        "columns": [
          { "key": "Category", "label": "Category" },
          { "key": "Day 1", "label": "Day 1" },
          { "key": "Day 2", "label": "Day 2" },
          { "key": "Day 3", "label": "Day 3" },
          { "key": "Day 4", "label": "Day 4" },
          { "key": "Day 5", "label": "Day 5" }
        ],
        "numericColumns": ["Day 1", "Day 2", "Day 3", "Day 4", "Day 5"]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "wrap": "wrap"
      },
      "children": ["quick_action_button_0", "quick_action_button_1"]
    },
    "quick_action_button_0": {
      "type": "Button",
      "props": {
        "label": "Tokyo Metro Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tokyometro.jp/en/subwaymap/"
          }
        }
      },
      "children": []
    },
    "quick_action_button_1": {
      "type": "Button",
      "props": {
        "label": "Shinjuku Dining"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.timeout.com/tokyo/restaurants/best-restaurants-in-shinjuku"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": ["source_button_0", "source_button_1"]
    },
    "source_button_0": {
      "type": "Button",
      "props": {
        "label": "Go Tokyo",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.gotokyo.org/en/"
          }
        }
      },
      "children": []
    },
    "source_button_1": {
      "type": "Button",
      "props": {
        "label": "Japan Guide",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan-guide.com/"
          }
        }
      },
      "children": []
    }
  }
}
